const item = $input.item.json;
const startedAt = new Date().toISOString();
const requestPart = String(item.requestId || 'request').replace(/[^a-zA-Z0-9_-]/g, '_');
const researchBatchId = `${requestPart}:${Date.now()}:${Math.random().toString(36).slice(2, 10)}`;

return [{
  json: {
    ...item,
    researchBatchId,
    researchStartedAt: startedAt,
    researchTimeoutMs: 30000
  }
}];

const item = $input.item.json;
const shortlist = item.playerSearch.shortlist;

return shortlist.map((candidate) => ({
  json: {
    ...item,
    researchCandidateName: candidate.name
  }
}));

const current = $input.item.json || {};
const candidate = current.researchCandidateName || 'unbekannter Kandidat';
const reason = (current.error && (current.error.message || current.error)) || 'Research-Child konnte nicht gestartet werden.';
const now = new Date().toISOString();

const researchResult = {
  candidate,
  club: null,
  contract: null,
  marketValue: null,
  injuries: null,
  news: [],
  source: 'Research-Dispatch fehlgeschlagen (keine Quelle verfuegbar)',
  timestamp: now,
  confidence: 0,
  uncertain: true,
  uncertaintyReason: String(reason)
};

return [{
  json: {
    ...current,
    researchRuntimeBatchId: current.researchBatchId,
    researchRuntimeCandidate: candidate,
    researchRuntimeStatus: 'dispatch_error',
    researchRuntimePayload: JSON.stringify(researchResult),
    researchRuntimeCompletedAt: now
  }
}];

const base = { ...$('Research-Lauf vorbereiten').first().json };
const expected = (base.playerSearch && Array.isArray(base.playerSearch.shortlist))
  ? base.playerSearch.shortlist.map((c) => c.name)
  : [];
const expectedSet = new Set(expected);
const rows = $input.all()
  .map((item) => item.json || {})
  .filter((row) => row.batchId === base.researchBatchId && expectedSet.has(row.candidate));

const latestByCandidate = new Map();
for (const row of rows) {
  const previous = latestByCandidate.get(row.candidate);
  if (!previous || String(row.completedAt || '') >= String(previous.completedAt || '')) {
    latestByCandidate.set(row.candidate, row);
  }
}

const elapsedMs = Date.now() - new Date(base.researchStartedAt).getTime();
const timedOut = elapsedMs >= Number(base.researchTimeoutMs || 30000);
const complete = expected.every((name) => latestByCandidate.has(name)) || timedOut;

const research = [];
for (const name of expected) {
  const row = latestByCandidate.get(name);
  if (!row) {
    if (timedOut) {
      research.push({
        candidate: name,
        club: null,
        contract: null,
        marketValue: null,
        injuries: null,
        news: [],
        source: 'Research-Timeout (keine Quelle verfuegbar)',
        timestamp: new Date().toISOString(),
        confidence: 0,
        uncertain: true,
        uncertaintyReason: `Research-Zweig fuer ${name} hat das Fan-in-Timeout von ${base.researchTimeoutMs || 30000} ms ueberschritten.`
      });
    }
    continue;
  }

  try {
    const parsed = typeof row.payload === 'string' ? JSON.parse(row.payload) : row.payload;
    if (!parsed || typeof parsed !== 'object') throw new Error('payload ist kein Objekt');
    research.push({
      ...parsed,
      candidate: parsed.candidate || name,
      uncertain: Boolean(parsed.uncertain),
      uncertaintyReason: parsed.uncertaintyReason ?? null
    });
  } catch (error) {
    research.push({
      candidate: name,
      club: null,
      contract: null,
      marketValue: null,
      injuries: null,
      news: [],
      source: 'Research-Ergebnis unlesbar',
      timestamp: row.completedAt || new Date().toISOString(),
      confidence: 0,
      uncertain: true,
      uncertaintyReason: `Persistiertes Research-Ergebnis konnte nicht gelesen werden: ${error.message}`
    });
  }
}

return [{
  json: {
    ...base,
    research,
    researchComplete: complete,
    researchTimedOut: timedOut,
    researchCompletedCandidates: [...latestByCandidate.keys()]
  }
}];

const item = $input.item.json;
const research = item.research;
const shortlistNames = (item.playerSearch && Array.isArray(item.playerSearch.shortlist)) ? item.playerSearch.shortlist.map((c) => c.name) : [];
const errors = [];

if (!Array.isArray(research) || research.length === 0) {
  errors.push('research fehlt oder ist leer.');
} else {
  const researchedNames = research.map((r) => r.candidate).filter(Boolean);
  const uniqueResearchedNames = new Set(researchedNames);
  const shortlistSet = new Set(shortlistNames);

  if (researchedNames.length !== uniqueResearchedNames.size) errors.push('research enthaelt denselben Kandidaten mehrfach.');
  const missing = shortlistNames.filter((name) => !uniqueResearchedNames.has(name));
  if (missing.length > 0) errors.push(`research deckt folgende Shortlist-Kandidaten nicht ab: ${missing.join(', ')}.`);
  const unexpected = [...uniqueResearchedNames].filter((name) => !shortlistSet.has(name));
  if (unexpected.length > 0) errors.push(`research enthaelt Kandidaten ausserhalb der Shortlist: ${unexpected.join(', ')}.`);

  research.forEach((r, idx) => {
    if (!r.candidate || !shortlistSet.has(r.candidate)) errors.push(`research[${idx}].candidate fehlt oder ist nicht Teil der Shortlist.`);
    if (typeof r.confidence !== 'number') errors.push(`research[${idx}].confidence fehlt oder ist keine Zahl.`);
    if (!r.source) errors.push(`research[${idx}].source fehlt.`);
    if (!r.timestamp) errors.push(`research[${idx}].timestamp fehlt.`);
    if (!Array.isArray(r.news)) errors.push(`research[${idx}].news ist kein Array.`);
    if (!r.uncertain) {
      if (!r.club) errors.push(`research[${idx}].club fehlt.`);
      if (!r.contract) errors.push(`research[${idx}].contract fehlt.`);
      if (!r.marketValue) errors.push(`research[${idx}].marketValue fehlt.`);
      if (!r.injuries) errors.push(`research[${idx}].injuries fehlt.`);
      if (Array.isArray(r.news) && r.news.length === 0) errors.push(`research[${idx}].news ist leer.`);
    }
  });

  if (research.every((r) => r.uncertain)) errors.push('Fuer keinen Kandidaten konnte eine Recherche erfolgreich durchgefuehrt werden.');
}

const valid = errors.length === 0;
const {
  researchBatchId,
  researchStartedAt,
  researchTimeoutMs,
  researchComplete,
  researchTimedOut,
  researchCompletedCandidates,
  ...cleanItem
} = item;
return [{ json: { ...cleanItem, research, valid, errorMessage: valid ? undefined : 'Die Recherche ist ungueltig und wird nicht fuer die Empfehlung verwendet.\n\n' + errors.join('\n') } }];

const item = $input.item.json;
if (item.valid === false) {
  throw new Error('[DUE_DILIGENCE] ' + (item.errorMessage || 'Due Diligence ist fehlgeschlagen.'));
}
return [{ json: { ...item, status: 'success' } }];
